+func runSession(t *testing.T) *sys.Session {
+	t.Helper()
+	env := append(os.Environ(), "GIT_CONFIG_GLOBAL=/dev/null", "GIT_CONFIG_NOSYSTEM=1", "GIT_TERMINAL_PROMPT=0",
+		"GIT_AUTHOR_NAME=T", "GIT_AUTHOR_EMAIL=t@example.invalid", "GIT_COMMITTER_NAME=T", "GIT_COMMITTER_EMAIL=t@example.invalid")
+	return sys.NewWith(env, t.TempDir())
+}
+
+func checkNames(checks []Check) []string {
+	var names []string
+	for _, c := range checks {
+		names = append(names, c.Check)
+	}
+	return names
+}
+
+func TestRunReportOrderInsideGitCheckout(t *testing.T) {
+	s := runSession(t)
+	root := gitRepo(t)
+	writeProjectFile(t, root, project.ConfigPath, "version: 1\n")
+	nested := filepath.Join(root, "services", "api")
+	if err := os.MkdirAll(nested, 0o755); err != nil {
+		t.Fatal(err)
+	}
+	in := Input{Project: nested, Version: "kogen dev", Home: t.TempDir()}
+	got := Run(s, in)
+	if names, want := strings.Join(checkNames(got), ","), "install,git,config,models"; names != want {
+		t.Fatalf("Run checks = %s, want %s: %+v", names, want, got)
+	}
+	_, wantGit := checkGit(s, in)
+	if wantGit.Status != "ok" {
+		t.Fatalf("the Git check of a configured checkout = %+v, want ok", wantGit)
+	}
+	if got[1] != wantGit {
+		t.Fatalf("git check = %+v, want %+v", got[1], wantGit)
+	}
+	if want := checkConfig(root); want.Status != "ok" || got[2] != want {
+		t.Fatalf("config check = %+v, want the repository root's %+v", got[2], want)
+	}
+	if want := checkModels(root, in); got[3] != want {
+		t.Fatalf("models check = %+v, want the repository root's %+v", got[3], want)
+	}
+	if got[3].Status != "fail" || !strings.HasPrefix(got[3].Detail, "shape: chatgpt has no stored login") {
+		t.Fatalf("models check = %+v, want the default lineup read from the repository root", got[3])
+	}
+}
+
+func TestRunReportOrderOutsideGitCheckout(t *testing.T) {
+	s := runSession(t)
+	dir := t.TempDir()
+	writeProjectFile(t, dir, project.ConfigPath, "version: 1\n")
+	writeProjectFile(t, dir, project.ModelsPath, "models:\n  shape: {provider: supergrok, model: grok-4.7, effort: high}\n")
+	in := Input{Project: dir, Version: "kogen dev", Home: t.TempDir()}
+	got := Run(s, in)
+	if names, want := strings.Join(checkNames(got), ","), "install,git,config,models"; names != want {
+		t.Fatalf("Run checks = %s, want %s: %+v", names, want, got)
+	}
+	if got[1].Status != "fail" || got[1].Detail != dir+" is not inside a Git repository" {
+		t.Fatalf("git check = %+v, want the outside-repository failure", got[1])
+	}
+	if want := checkConfig(dir); want.Status != "ok" || got[2] != want {
+		t.Fatalf("config check = %+v, want the project directory's %+v", got[2], want)
+	}
+	want := checkModels(dir, in)
+	if got[3] != want || got[3].Status != "fail" || !strings.HasPrefix(got[3].Detail, "shape: supergrok has no stored login") {
+		t.Fatalf("models check = %+v, want the project directory's %+v", got[3], want)
+	}
+}

