+func byName(checks []Check, name string) Check {
+	for _, c := range checks {
+		if c.Check == name {
+			return c
+		}
+	}
+	return Check{}
+}
+
+func sortedNames(checks []Check) string {
+	names := checkNames(checks)
+	slices.Sort(names)
+	return strings.Join(names, ",")
+}

